GeM.content:
class CustomPool(nn.Module):
    """Generalized Mean (GeM) Pooling.

    Learnable generalized mean with parameter p (init=3.0).
    Interpolates between average pooling (p=1) and max pooling (p->inf).

    """

    def __init__(self):
        super().__init__()
        self.p = nn.Parameter(torch.ones(1) * 3.0)
        self.eps = 1e-6

    def forward(self, x):
        p = self.p.clamp(min=1.0)
        x = x.clamp(min=self.eps)
        return F.adaptive_avg_pool2d(x.pow(p), 1).pow(1.0 / p).view(x.size(0), -1)

Avg + Max.content:
class CustomPool(nn.Module):
    """Average + Max Pooling.

    Element-wise mean of global average pooling and global max pooling.
    Combines mean-field statistics with peak activations.
    """

    def __init__(self):
        super().__init__()

    def forward(self, x):
        avg = F.adaptive_avg_pool2d(x, 1)
        mx = F.adaptive_max_pool2d(x, 1)
        return ((avg + mx) / 2).view(x.size(0), -1)

L1 + KL.content:
class VAELoss(nn.Module):
    """Basic VAE loss: L1 reconstruction + KL divergence."""

    def __init__(self, device):
        super().__init__()
        self.kl_weight = 1e-6

    def forward(self, recon, target, posterior, step):
        rec_loss = F.l1_loss(recon, target)
        kl_loss = posterior.kl().mean()
        loss = rec_loss + self.kl_weight * kl_loss
        return loss, {
            "rec_loss": rec_loss.item(),
            "kl_loss": kl_loss.item(),
        }

