# OPD (Lu et al. 2025 / Qwen3 report) — per-token reverse KL: KL(p_S || p_T).
student_logits = student_logits / temperature
teacher_logits = teacher_logits / temperature
student_log_probs = F.log_softmax(student_logits, dim=-1)
teacher_log_probs = F.log_softmax(teacher_logits, dim=-1)

# KL(p_S || p_T) per token, summed over vocab.
# F.kl_div(input=log_q, target=log_p, log_target=True) = Σ_v p · (log p - log q).
# With input=teacher_log_probs and target=student_log_probs this gives KL(p_S || p_T).
per_token = F.kl_div(
    teacher_log_probs, student_log_probs, reduction="none", log_target=True
).sum(dim=-1)  # [B, T]

if labels is not None:
    mask = labels != -100
    per_token = per_token[mask]
    denom = mask.sum().clamp_min(1)
else:
    denom = torch.tensor(max(per_token.numel(), 1), device=per_token.device, dtype=per_token.dtype)

if reduction == "batchmean":
    return per_token.sum() / denom
elif reduction == "sum":
    return per_token.sum()
elif reduction == "mean":
    return per_token.mean()
return per_token

taid.content:
# TAID (Shing et al., ICLR'25 Spotlight) — logit-space interpolation, linear schedule.
t_start = 0.4
if total_steps and total_steps > 0:
    t_val = t_start + (1.0 - t_start) * min(1.0, max(0.0, step / float(total_steps)))
else:
    t_val = 0.7

student_logits = student_logits / temperature
teacher_logits = teacher_logits / temperature

# Target logits = (1-t) * student.detach() + t * teacher.  Detach is critical so
# the target distribution carries no gradient back through the student branch.
t = torch.tensor(t_val, dtype=student_logits.dtype, device=student_logits.device)
target_logits = (1 - t) * student_logits.detach() + t * teacher_logits
target_log_probs = F.log_softmax(target_logits, dim=-1)
student_log_probs = F.log_softmax(student_logits, dim=-1)

# KL(target || student) = Σ_v p_target · (log p_target - log p_student)
# F.kl_div(input=log_q, target=log_p, log_target=True) returns KL(p || q),
# so input=student_log_probs, target=target_log_probs gives KL(target || student).
per_token = F.kl_div(
    student_log_probs, target_log_probs, reduction="none", log_target=True
).sum(dim=-1)

if labels is not None:
    mask = labels != -100
    per_token = per_token[mask]
    denom = mask.sum().clamp_min(1)
else:
    denom = torch.tensor(max(per_token.numel(), 1), device=per_token.device, dtype=per_token.dtype)

if reduction == "batchmean":
    return per_token.sum() / denom
elif reduction == "sum":
    return per_token.sum()
elif reduction == "mean":
    return per_token.mean()
return per_token

Untied Embeddings.content:
class TokenEmbedding(nn.Module):
    """Token + position embedding with UNTIED lm_head weight."""
    def __init__(self, config):
        super().__init__()
        self.wte = nn.Embedding(config.vocab_size, config.n_embd)
        self.wpe = nn.Embedding(config.block_size, config.n_embd)
        self.drop = nn.Dropout(config.dropout)
        self.block_size = config.block_size
        self.n_embd = config.n_embd
        self.vocab_size = config.vocab_size
        # Separate output projection weight (not tied to wte)
        self._lm_head_weight = nn.Parameter(torch.empty(config.vocab_size, config.n_embd))
        nn.init.zeros_(self._lm_head_weight)

    def forward(self, idx):
        b, t = idx.size()
        tok_emb = self.wte(idx)
        pos = torch.arange(0, t, dtype=torch.long, device=idx.device)
        pos_emb = self.wpe(pos)
        return self.drop(tok_emb + pos_emb)

    def get_lm_head_weight(self):
        return self._lm_head_weight

    def get_num_pos_params(self):
        return self.wpe.weight.numel()

