        o, _, _ = self._attn_forward(x)
        return o

WSD (Warmup-Stable-Decay).content:
def get_lr(it, warmup_iters, lr_decay_iters, learning_rate, min_lr):
    """WSD (Warmup-Stable-Decay) learning rate schedule."""
    # Warmup phase
    if it < warmup_iters:
        return learning_rate * (it + 1) / (warmup_iters + 1)
    # Decay phase: last 20% of training
    decay_start = int(lr_decay_iters * 0.8)
    if it >= decay_start:
        decay_ratio = (it - decay_start) / (lr_decay_iters - decay_start)
        return min_lr + (learning_rate - min_lr) * (1.0 - decay_ratio)
    # Stable phase: constant LR
    return learning_rate

Trapezoidal.content:
def get_lr(it, warmup_iters, lr_decay_iters, learning_rate, min_lr):
    """Trapezoidal learning rate schedule: warmup, constant plateau, cooldown."""
    if it > lr_decay_iters:
        return min_lr
    # Warmup phase
    if it < warmup_iters:
        return learning_rate * (it + 1) / (warmup_iters + 1)
    # Cooldown phase: last 40% of training
    cooldown_start = int(lr_decay_iters * 0.6)
    if it >= cooldown_start:
        t = (it - cooldown_start) / (lr_decay_iters - cooldown_start)
        return min_lr + (learning_rate - min_lr) * (1.0 - t)
    # Constant plateau
    return learning_rate

