def compute_custom_kl_penalty(
    logprob: torch.Tensor,
    ref_logprob: torch.Tensor,
) -> torch.Tensor:
    """k2 (mse) estimator: 0.5 * (logprob - ref_logprob) ** 2."""
    return 0.5 * (logprob - ref_logprob).square()

