class CustomFewShotMethod(FewShotClassifier):
    """Prototypical Networks (Snell et al., 2017).

    Compute class prototypes as the mean feature vector of support examples,
    then classify queries by negative Euclidean distance to prototypes.
    """

    def __init__(self):
        backbone = make_backbone(use_pooling=True)
        super().__init__(backbone=backbone, use_softmax=False)

    def process_support_set(self, support_images: Tensor, support_labels: Tensor):
        self.compute_prototypes_and_store_support_set(support_images, support_labels)

    def forward(self, query_images: Tensor) -> Tensor:
        query_features = self.compute_features(query_images)
        scores = self.l2_distance_to_prototypes(query_features)
        return self.softmax_if_specified(scores)

    @staticmethod
    def is_transductive() -> bool:
        return False

    def compute_loss(self, scores: Tensor, labels: Tensor) -> Tensor:
        return F.cross_entropy(scores, labels)

RelationNet.content:
class _RelationModule(nn.Module):
    """CNN relation module from Sung et al. (2018)."""

    def __init__(self, feature_dimension: int, inner_channels: int = 8):
        super().__init__()
        self.module = nn.Sequential(
            nn.Sequential(
                nn.Conv2d(feature_dimension * 2, feature_dimension, kernel_size=3, padding=1),
                nn.BatchNorm2d(feature_dimension, momentum=1, affine=True),
                nn.ReLU(),
                nn.AdaptiveMaxPool2d((5, 5)),
            ),
            nn.Sequential(
                nn.Conv2d(feature_dimension, feature_dimension, kernel_size=3, padding=0),
                nn.BatchNorm2d(feature_dimension, momentum=1, affine=True),
                nn.ReLU(),
                nn.AdaptiveMaxPool2d((1, 1)),
            ),
            nn.Flatten(),
            nn.Linear(feature_dimension, inner_channels),
            nn.ReLU(),
            nn.Linear(inner_channels, 1),
            nn.Sigmoid(),
        )

    def forward(self, x):
        return self.module(x)


class CustomFewShotMethod(FewShotClassifier):
    """Relation Networks (Sung et al., 2018).

    Extracts feature maps (not pooled vectors) from support and query images.
    Computes class prototypes as mean feature maps, concatenates each query-prototype
    pair, and feeds them through a learned relation module to get relation scores.
    Uses MSE loss since output represents relation scores in [0, 1].
    """

    def __init__(self):
        backbone = make_backbone(use_pooling=False)  # Need feature maps, not vectors
        super().__init__(backbone=backbone, use_softmax=False)
        self.feature_dimension = FEATURE_DIMENSION
        self.relation_module = _RelationModule(self.feature_dimension)

    def process_support_set(self, support_images: Tensor, support_labels: Tensor):
        support_features = self.compute_features(support_images)
        n_way = len(torch.unique(support_labels))
        self.prototypes = torch.cat(
            [
                support_features[support_labels == label].mean(0, keepdim=True)
                for label in range(n_way)
            ]
        )

    def forward(self, query_images: Tensor) -> Tensor:
        query_features = self.compute_features(query_images)
        n_queries = query_features.shape[0]
        n_prototypes = self.prototypes.shape[0]

        # Build pairs: [n_queries * n_prototypes, 2 * C, H, W]
        query_prototype_pairs = torch.cat(
            (
                self.prototypes.unsqueeze(0).expand(n_queries, -1, -1, -1, -1),
                query_features.unsqueeze(1).expand(-1, n_prototypes, -1, -1, -1),
            ),
            dim=2,
        ).view(-1, 2 * self.feature_dimension, *query_features.shape[2:])

        relation_scores = self.relation_module(query_prototype_pairs).view(
            n_queries, n_prototypes
        )
        return self.softmax_if_specified(relation_scores)

    @staticmethod
    def is_transductive() -> bool:
        return False

    def compute_loss(self, scores: Tensor, labels: Tensor) -> Tensor:
        # RelationNet uses MSE with one-hot labels
        one_hot = F.one_hot(labels, num_classes=scores.shape[1]).float()
        return F.mse_loss(scores, one_hot)

Meta-SGD.content:
class InnerLoopOptimizer:
    """Meta-SGD inner-loop optimizer (Li et al., 2017).

    Learns a per-parameter learning rate vector that is meta-optimized
    by the outer loop. Each model parameter gets a corresponding learnable
    learning rate tensor of the same shape, initialized to inner_lr.
    """

    def __init__(self, model: nn.Module, inner_lr: float = INNER_LR):
        self.inner_lr = inner_lr
        # Create per-parameter learnable learning rates
        self.lrs = nn.ParameterList([
            nn.Parameter(torch.ones_like(p) * inner_lr)
            for p in model.parameters()
        ])

    def adapt(self, model: nn.Module, support_x: Tensor, support_y: Tensor,
              n_steps: int) -> nn.Module:
        model.train()
        for _ in range(n_steps):
            loss = F.cross_entropy(model(support_x), support_y)
            grads = torch.autograd.grad(
                loss, model.parameters(), create_graph=True
            )
            updates = [-lr * g for g, lr in zip(grads, self.lrs)]
            l2l.update_module(model, updates=updates)
        return model

    def meta_parameters(self) -> List[Tensor]:
        return list(self.lrs.parameters())

ANIL.content:
class InnerLoopOptimizer:
    """ANIL inner-loop optimizer (Raghu et al., 2019).

    Almost No Inner Loop: only adapts the final classification head
    during inner-loop adaptation. The feature extractor backbone is
    frozen, relying on feature reuse from the meta-initialization.
    """

    def __init__(self, model: nn.Module, inner_lr: float = INNER_LR):
        self.inner_lr = inner_lr
        # Identify head parameters (the last linear layer: classifier)
        # CNN4 structure: features (CNN4Backbone) -> classifier (Linear)
        self._head_param_names = set()
        for name, _ in model.named_parameters():
            if "classifier" in name:
                self._head_param_names.add(name)

    def adapt(self, model: nn.Module, support_x: Tensor, support_y: Tensor,
              n_steps: int) -> nn.Module:
        model.train()
        for _ in range(n_steps):
            # Re-identify head params each step because l2l.update_module
            # replaces parameter objects (new ids), so stale references
            # from a previous step would cause all updates to be zero.
            head_params = []
            head_ids = set()
            for name, p in model.named_parameters():
                if name in self._head_param_names:
                    head_params.append(p)
                    head_ids.add(id(p))

            loss = F.cross_entropy(model(support_x), support_y)
            grads = torch.autograd.grad(
                loss, head_params, create_graph=True
            )
            grad_map = {id(p): g for p, g in zip(head_params, grads)}
            updates = [
                -self.inner_lr * grad_map[id(p)] if id(p) in head_ids
                else torch.zeros_like(p)
                for p in model.parameters()
            ]
            l2l.update_module(model, updates=updates)
        return model

    def meta_parameters(self) -> List[Tensor]:
        return []

Least Confidence.content:
class CustomSampling(Strategy):
    """Least Confidence (Uncertainty Sampling) — selects samples with lowest
    maximum predicted probability."""

    def __init__(self, X, Y, idxs_lb, net, handler, args):
        super(CustomSampling, self).__init__(X, Y, idxs_lb, net, handler, args)

    def query(self, n):
        idxs_unlabeled = np.arange(self.n_pool)[~self.idxs_lb]
        probs = self.predict_prob(self.X[idxs_unlabeled], np.asarray(self.Y)[idxs_unlabeled])
        U = probs.max(1)[0]
        return idxs_unlabeled[U.sort()[1][:n]]

