class CustomImputer(BaseEstimator, TransformerMixin):
    """KNN Imputation: impute using K-nearest neighbors.

    Uses sklearn.impute.KNNImputer with n_neighbors=5, distance weighting.
    Reference: Troyanskaya et al. (2001).
